<?php /** Shared compact identity cards: same 48px emblem for every affiliation and trait. */ ?>
<div class="rpg-identity-cards" aria-label="Identità e appartenenze">
 <?php foreach($d['cards'] as $card):$kind=$card['kind']; ?>
 <details class="rpg-identity-card" data-profile-card="<?=$h($kind)?>"<?php if($kind==='alignment'): ?> data-profile-alignment="<?=$h($d['alignment']['code'])?>"<?php endif; ?>>
  <summary><span class="rpg-card-media-group"><span class="rpg-card-emblem" data-profile-card-icon<?php if($kind==='sex'): ?> data-sex="<?=$d['sex']==='Femmina'?'female':'male'?>"<?php endif; ?>><?php if($card['src']): ?><img src="<?=$h($card['src'])?>" alt="" width="48" height="48"><?php else: ?><span data-icon="<?=$h($card['icon'])?>" aria-hidden="true"></span><?php endif; ?></span><?php if($kind==='race'&&!empty($sheet['transformation']['visible'])):$form=$sheet['transformation']; ?><button type="button" class="rpg-card-transform" data-profile-transform data-transform-state="<?=$h(json_encode($form,JSON_UNESCAPED_UNICODE))?>" data-icon="moon" title="<?=$h($form['label'].' · '.$form['description'])?>" aria-label="<?=$h($form['label'])?>" aria-pressed="<?=$form['form']!=='human'?'true':'false'?>"></button><?php endif; ?></span><span class="rpg-card-copy"><small><?=$h($card['label'])?></small><strong title="<?=$h($card['name'])?>"><?=$h($card['name'])?></strong></span></summary>
  <div class="rpg-card-description"><?php if($card['detail']): ?><strong><?=$h($card['detail'])?></strong><?php endif; ?><?php if($card['description']): ?><p><?=$h($card['description'])?></p><?php endif; ?><?php if($card['url']): ?><a href="<?=$h($card['url'])?>"><?=$kind==='alignment'?'Guida agli allineamenti':'Apri '.($kind==='race'?'razza e abilità':($kind==='city'?'città e cariche':'gerarchia'))?> →</a><?php endif; ?><?php if($kind==='race'&&empty($sheet['transformation']['visible'])):foreach($sheet['actions'] as $action):if($action['icon']!=='moon')continue; ?><a href="<?=$h($action['url'])?>"><?=$h($action['title'])?></a><?php endforeach;endif; ?></div>
 </details>
 <?php endforeach; ?>
</div>
